CREATE TABLE epw_document(id INTEGER PRIMARY KEY CHECK(id=1),schema_identity TEXT NOT NULL,design_conditions TEXT NOT NULL,typical_extreme_periods TEXT NOT NULL,ground_temperatures TEXT NOT NULL,holidays_dst TEXT NOT NULL,comments_1 TEXT NOT NULL,comments_2 TEXT NOT NULL);
CREATE TABLE epw_location(id INTEGER PRIMARY KEY REFERENCES epw_document(id) CHECK(id=1),city TEXT NOT NULL,state_province TEXT NOT NULL,country TEXT NOT NULL,source TEXT NOT NULL,wmo TEXT NOT NULL,latitude TEXT NOT NULL,longitude TEXT NOT NULL,time_zone TEXT NOT NULL,elevation TEXT NOT NULL);
CREATE TABLE epw_data_periods(id INTEGER PRIMARY KEY REFERENCES epw_document(id) CHECK(id=1),records_per_hour INTEGER NOT NULL CHECK(records_per_hour BETWEEN 0 AND 4294967295));
CREATE TABLE epw_data_period(id INTEGER PRIMARY KEY,data_periods_id INTEGER NOT NULL REFERENCES epw_data_periods(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),name TEXT NOT NULL,start_day_of_week TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL);
CREATE TABLE epw_record(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES epw_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),year TEXT NOT NULL,month TEXT NOT NULL,day TEXT NOT NULL,hour TEXT NOT NULL,minute TEXT NOT NULL,data_source_uncertainty TEXT NOT NULL,dry_bulb_temp TEXT NOT NULL,dew_point_temp TEXT NOT NULL,relative_humidity TEXT NOT NULL,atmospheric_pressure TEXT NOT NULL,extraterrestrial_horizontal_radiation TEXT NOT NULL,extraterrestrial_direct_normal_radiation TEXT NOT NULL,horizontal_infrared_radiation TEXT NOT NULL,global_horizontal_radiation TEXT NOT NULL,direct_normal_radiation TEXT NOT NULL,diffuse_horizontal_radiation TEXT NOT NULL,global_horizontal_illuminance TEXT NOT NULL,direct_normal_illuminance TEXT NOT NULL,diffuse_horizontal_illuminance TEXT NOT NULL,zenith_luminance TEXT NOT NULL,wind_direction TEXT NOT NULL,wind_speed TEXT NOT NULL,total_sky_cover TEXT NOT NULL,opaque_sky_cover TEXT NOT NULL,visibility TEXT NOT NULL,ceiling_height TEXT NOT NULL,present_weather_observation TEXT NOT NULL,present_weather_codes TEXT NOT NULL,precipitable_water TEXT NOT NULL,aerosol_optical_depth TEXT NOT NULL,snow_depth TEXT NOT NULL,days_since_last_snowfall TEXT NOT NULL,albedo TEXT NOT NULL,liquid_precip_depth TEXT NOT NULL,liquid_precip_quantity TEXT NOT NULL);
